"""200 unique Structure & Written Expression items (5 packs x [15 Part A + 25 Part B = 40]) for TOEFL ITP Level 1."""

from pack_schema_helpers import make_q, rotated_mcq

# Tuple formats:
# Part A: (prompt, [o0, o1, o2, o3], ans_idx, mod, diff, exp)
# Part B: (sentence_with_ABCD, error_idx, mod, diff, exp)  -- auto-extracts [A]..[D] segments!

import re

_ABCD_RE = re.compile(r"(\[A\]\s+.+?)\s+(\[B\]\s+.+?)\s+(\[C\]\s+.+?)\s+(\[D\]\s+.+?)(?:\.|$)")


def _build_we_item(qid: str, prompt_raw: str, error_idx: int, mod: str, diff: str, exp: str) -> dict:
    # Extract four bracketed phrases marked cleanly as '[A] span ... [B] span ...'
    m = re.findall(r"\[([A-D])\]\s+([^\[.;?!]+)", prompt_raw)
    assert len(m) == 4, f"{qid}: Expected 4 [A]..[D] tags in '{prompt_raw}'"
    opts = [f"[{tag}] {span.strip()}" for tag, span in m]
    assert 0 <= error_idx < 4, f"{qid}: bad error_idx {error_idx}"
    return make_q(
        qid=qid,
        section="STRUCTURE",
        task_type="ERROR_IDENTIFICATION",
        prompt=prompt_raw,
        options=opts,
        answer=opts[error_idx],
        explanation=exp,
        rationale_source=mod,
        difficulty=diff,
    )


